import numpy as np
t=df['t'].values;A=df['A'].values;y=df['dA_dt'].values
best=None
one=np.ones_like(t)
for p in [0.5,0.75,1,1.25,1.5,2]:
  for b in np.linspace(0.5,1.5,21):
    for k in np.linspace(3,10,29):
        X=np.column_stack([np.exp(-b*t)/t**p,one,t,t**2,A**2*t/(t+k)])
        c=np.linalg.lstsq(X,y,rcond=None)[0]; r=y-X@c
        e=np.mean(r**2)/np.var(y)
        if best is None or e<best[0]: best=(e,p,b,k,c)
print("%.3e p=%.2f b=%.3f k=%.3f"%(best[0],best[1],best[2],best[3]), np.round(best[4],4))
# also h with power
best2=None
for p in [1]:
  for b in np.linspace(0.8,1.2,21):
    for k in np.linspace(4,9,26):
