        X=np.column_stack([np.exp(-b*t)/t**p,one,t,t**2,A**2*t**q/(t**q+k)])
        c=np.linalg.lstsq(X,y,rcond=None)[0]; r=y-X@c
        e=np.mean(r**2)/np.var(y)
        if best2 is None or e<best2[0]: best2=(e,b,k,q,c)
print("%.3e b=%.3f k=%.3f q=%.2f"%(best2[0],best2[1],best2[2],best2[3]), np.round(best2[4],4))
